<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Что такое машиночитаемая доверенность для казначейства?", "acceptedAnswer": {"@type": "Answer", "text": "Это электронная доверенность в виде xml-файла, подписанного квалифицированной электронной подписью руководителя, которая подтверждает полномочия работника подписывать документы от имени организации своим личным сертификатом физического лица в ГИИС «Электронный бюджет»."}}, {"@type": "Question", "name": "Когда нужна МЧД для казначейства?", "acceptedAnswer": {"@type": "Answer", "text": "Когда документы от имени организации подписывает не руководитель, а уполномоченный сотрудник своим личным сертификатом физического лица. Если подписывает сам руководитель сертификатом организации, отдельная МЧД не требуется."}}, {"@type": "Question", "name": "Обязательна ли МЧД в «Электронном бюджете»?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Применение МЧД в подсистеме учёта и регистрации казначейского сопровождения ГИИС «Электронный бюджет» обязательно с 1 июня 2025 года. Без действующей доверенности подпись уполномоченного работника не принимается."}}, {"@type": "Question", "name": "В каком формате оформляется МЧД?", "acceptedAnswer": {"@type": "Answer", "text": "В ГИИС «Электронный бюджет» применяется универсальный формат машиночитаемой доверенности — формат 003. Доверенность в устаревшем или неподходящем формате система может не принять."}}, {"@type": "Question", "name": "Как оформить машиночитаемую доверенность?", "acceptedAnswer": {"@type": "Answer", "text": "Убедиться, что у руководителя и работника есть квалифицированные сертификаты, определить полномочия, создать доверенность в универсальном формате через распределённый реестр ФНС или специализированный сервис и подписать её квалифицированной подписью руководителя."}}, {"@type": "Question", "name": "Кто подписывает МЧД?", "acceptedAnswer": {"@type": "Answer", "text": "Доверенность подписывает руководитель организации (доверитель) своей квалифицированной электронной подписью. Именно его подпись придаёт МЧД юридическую силу и подтверждает передачу полномочий."}}, {"@type": "Question", "name": "Что делать, если документ не подписывается в системе?", "acceptedAnswer": {"@type": "Answer", "text": "Проверить статус МЧД подписанта: действует ли она, не истёк ли срок, отозвана ли, содержит ли нужные полномочия. Часто причина именно в доверенности, а не в сертификате или настройке рабочего места."}}, {"@type": "Question", "name": "На какой срок выдаётся МЧД?", "acceptedAnswer": {"@type": "Answer", "text": "На срок, указанный в самой доверенности. По его истечении доверенность перестаёт действовать, и подписант теряет возможность подписывать документы, пока не оформлена новая МЧД."}}, {"@type": "Question", "name": "Можно ли отозвать машиночитаемую доверенность?", "acceptedAnswer": {"@type": "Answer", "text": "Да. МЧД можно отозвать досрочно — например, при увольнении работника, изменении полномочий или смене руководителя. Отзыв прекращает действие доверенности и подпись бывшего уполномоченного лица перестаёт приниматься."}}, {"@type": "Question", "name": "Нужна ли отдельная МЧД на каждого подписанта?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Руководитель формирует отдельную доверенность на каждого работника с тем набором полномочий, который соответствует его праву подписи и фактической роли в системе."}}, {"@type": "Question", "name": "Нужна ли доверенность для УФК и какая?", "acceptedAnswer": {"@type": "Answer", "text": "Да, если документы в казначействе подписывает не руководитель, а сотрудник. Доверенность для УФК оформляется как машиночитаемая доверенность (МЧД) — xml-файл, подписанный квалифицированной электронной подписью руководителя, — и подтверждает полномочия в «Электронном бюджете». Бумажная доверенность при электронной подаче не нужна."}}]}
</script>
